<script>
    function switchTab(tabName) {
        // Prevent default link behavior
        event.preventDefault();

        // Update Nav Active State
        const navItems = document.querySelectorAll('.nav-item');
        navItems.forEach(item => item.classList.remove('active'));

        // Find clicked item and activate it
        // Simple logic: find the one that was clicked via event target traversal or just match text
        // For this demo, we'll rely on the specific onclick handler passed tabName
        let activeNav;
        if(tabName === 'home') activeNav = navItems[0];
        else if(tabName === 'create') activeNav = navItems[1];
        else if(tabName === 'explore') activeNav = navItems[2];
        else if(tabName === 'gallery') activeNav = navItems[3];
        else if(tabName === 'profile') activeNav = navItems[4];

        if(activeNav) activeNav.classList.add('active');

        // Switch Pages
        const pageHome = document.getElementById('page-home');
        const pageExplore = document.getElementById('page-explore');

        if (tabName === 'home') {
            pageHome.classList.add('active');
            pageExplore.classList.remove('active');
        } else if (tabName === 'explore') {
            pageHome.classList.remove('active');
            pageExplore.classList.add('active');
        } 
        // Other tabs would go here
    }

    // Segment Control Logic (Visual only)
    const segments = document.querySelectorAll('.segment-option');
    const indicator = document.querySelector('.segment-indicator');

    segments.forEach((seg, index) => {
        seg.addEventListener('click', () => {
            segments.forEach(s => s.classList.remove('active'));
            seg.classList.add('active');
            // Move indicator
            // Width is approx 85px from CSS
            indicator.style.transform = `translateX(${index * 88}px)`; 
        });
    });
</script>

